/**
 * Bounded, provider-specific terminal-result lane. It accepts only the
 * canonical adapter events emitted by the provider CLI and never examines
 * stderr, tool-log payloads, or arbitrary passthrough chunks as evidence.
 */
export const MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION = 'lattice.managed_review_final_proposal.v1' as const;

export interface ManagedReviewFinalEnvelopeReadManifest extends Record<string, unknown> {
  filesReadFully: string[];
  filesTriagedByName: string[];
  scanEscalationReason: string | null;
  candidateSpecSetDigest?: string;
  corpusDigest?: string;
}

export interface ManagedReviewFinalEnvelopeRecord extends Record<string, unknown> {
  schemaVersion: typeof MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION;
  storyId: string;
  providerAgent: string;
  lane: string;
  reviewRunId: string;
  conclusion: 'pass' | 'findings';
  note?: string;
  findings?: unknown[];
  readManifest: ManagedReviewFinalEnvelopeReadManifest;
}

export type ManagedReviewFinalEnvelopeClassification =
  | { kind: 'ordinary' }
  | { kind: 'malformed' }
  | { kind: 'valid'; envelope: ManagedReviewFinalEnvelopeRecord };

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every(item => typeof item === 'string');
}

/**
 * Classify one provider-owned final assistant text without treating ordinary
 * Codex progress messages as proposal candidates. A message that explicitly
 * names the managed proposal schema remains fail-closed when malformed; valid
 * envelopes receive a second semantic/provenance validation in the managed
 * worker before any immutable proposal is written.
 */
export function classifyManagedReviewFinalEnvelope(text: string): ManagedReviewFinalEnvelopeClassification {
  const trimmed = text.trim();
  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
      ? { kind: 'malformed' }
      : { kind: 'ordinary' };
  }
  if (!isPlainRecord(parsed)) return { kind: 'ordinary' };
  if (parsed.schemaVersion !== MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION) {
    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
      ? { kind: 'malformed' }
      : { kind: 'ordinary' };
  }

  const conclusion = parsed.conclusion;
  const allowed = new Set([
    'schemaVersion', 'storyId', 'providerAgent', 'lane', 'reviewRunId', 'conclusion',
    'readManifest', 'readLog', 'readDiagnostics', conclusion === 'pass' ? 'note' : 'findings',
  ]);
  const readManifest = parsed.readManifest;
  const validReadManifest = isPlainRecord(readManifest)
    && isStringArray(readManifest.filesReadFully)
    && isStringArray(readManifest.filesTriagedByName)
    && (readManifest.scanEscalationReason === null || typeof readManifest.scanEscalationReason === 'string')
    && (readManifest.candidateSpecSetDigest === undefined || typeof readManifest.candidateSpecSetDigest === 'string')
    && (readManifest.corpusDigest === undefined || typeof readManifest.corpusDigest === 'string');
  const validConclusionPayload = conclusion === 'pass'
    ? typeof parsed.note === 'string'
    : conclusion === 'findings' && Array.isArray(parsed.findings);
  if (Object.keys(parsed).some(key => !allowed.has(key))
    || typeof parsed.storyId !== 'string'
    || typeof parsed.providerAgent !== 'string'
    || typeof parsed.lane !== 'string'
    || typeof parsed.reviewRunId !== 'string'
    || !validReadManifest
    || !validConclusionPayload
    || (parsed.readLog !== undefined && !isPlainRecord(parsed.readLog))
    || (parsed.readDiagnostics !== undefined && !Array.isArray(parsed.readDiagnostics))) {
    return { kind: 'malformed' };
  }
  return { kind: 'valid', envelope: parsed as ManagedReviewFinalEnvelopeRecord };
}

export class FinalAssistantResultScanner {
  private partial = '';
  private skippingCandidate = false;
  private result: string | null = null;
  private candidateCount = 0;
  private candidateTruncated = false;

  constructor(
    private readonly host: HostRunHost | undefined,
    private readonly cap: number = HOST_RUN_FINAL_ASSISTANT_RESULT_CAP,
  ) {}

  push(text: string): void {
    if ((this.host !== 'codex' && this.host !== 'claude') || text.length === 0) return;
    let data = text;
    while (data.length > 0) {
      const nl = data.indexOf('\n');
      if (nl === -1) {
        if (this.skippingCandidate) return;
        if (this.partial.length + data.length > this.cap) {
          this.markOversizeCandidate(`${this.partial}${data.slice(0, Math.max(0, this.cap - this.partial.length))}`);
          this.partial = '';
    const importWorkers = [0, 1].map(index => {
      const readyPath = join(root, `import-worker-${index}.ready`);
      const resultPath = join(root, `import-worker-${index}.result`);
      const child = spawn(process.execPath, [
        SELF, '--import-worker', root, submitted.runId, 'AUTO',
        readyPath, importBarrier, resultPath,
      ], { cwd: root, stdio: 'ignore' });
      return { child, exit: waitForExit(child), readyPath, resultPath };
    });
    await eventually(async () => importWorkers.every(worker => {
      try { readFileSync(worker.readyPath); return true; } catch { return false; }
    }), 'concurrent import workers did not reach the pre-terminal barrier');
    writeFileSync(importBarrier, 'go');
    releaseTerminal();
    await eventually(async () => {
      const status = await getManagedHostRunStatus({ root, runId: submitted.runId });
      return status.run.state === 'completed';
    }, 'managed reviewer did not complete');
    const receipt = managedHostRunReceipt(root, submitted.runId);
    assert.deepEqual(await Promise.all(importWorkers.map(worker => worker.exit)), [0, 0],
      'real importer processes waiting before terminal creation both converge cleanly after the exclusive receipt appears');
    const concurrentImportResults = importWorkers.map(worker => readFileSync(worker.resultPath, 'utf8'));
    const handlers = createManagedReviewEvidenceHandlers({ store, root, scanRoot: join(root, 'packages/main') });

    // B-137a: the formal managed path consumes only the provider adapter's
    // bounded final assistant result. A tool shell is not required to inherit a
    // proposal capability and arbitrary streamed output is not an evidence
    // source. This injected runner is the same public adapter seam used by the
    // production Codex/Claude runners.
    const finalEnvelope = JSON.stringify({
      schemaVersion: 'lattice.managed_review_final_proposal.v1',
      storyId: STORY_ID,
      providerAgent: LANE,
      lane: LANE,
      reviewRunId: REVIEW_RUN_ID,
      conclusion: 'pass',
      note: 'The provider reviewed the exact managed material and found no blocking issue.',
      readManifest: {
        filesReadFully: ['packages/main/src/example.ts'],
        filesTriagedByName: [],
        scanEscalationReason: null,
      },
    });
    const codexMultiMessageRunner: HostRunRunner = plan => defaultHostRunRunner({
      ...plan,
      command: process.execPath,
      argv: ['-e', `for (const event of ${JSON.stringify([
        { type: 'item.completed', item: { type: 'agent_message', text: 'DISPATCH_START reviewer accepted the managed assignment' } },
        { type: 'item.completed', item: { type: 'reasoning', text: 'private reasoning is not a proposal candidate' } },
        { type: 'item.completed', item: { type: 'command_execution', aggregated_output: finalEnvelope } },
        { type: 'item.completed', item: { type: 'agent_message', text: 'Reviewed the first evidence group; continuing with adversarial paths.' } },
        { type: 'item.completed', item: { type: 'agent_message', text: finalEnvelope } },
      ])}) process.stdout.write(JSON.stringify(event) + '\\n');`],
    });
    const finalResultRun = await createHostRunHandlers(
      { store, root, scanRoot: join(root, 'packages/main') },
      { runner: codexMultiMessageRunner },
    ).host_run({
      host: 'codex', storyId: STORY_ID, agentType: LANE, reviewRunId: REVIEW_RUN_ID, lane: LANE,
      managedReview: true, detach: true, deadlineMs: 5_000, json: true,
    }) as HostRunDetachResult;
    await eventually(async () => (await getManagedHostRunStatus({ root, runId: finalResultRun.run.runId })).run.terminal !== null,
      'final-result managed reviewer did not reach terminal');
    const finalResultReceipt = managedHostRunReceipt(root, finalResultRun.run.runId);
    assert.equal(finalResultReceipt.state, 'completed', 'an exact bounded final proposal completes the formal managed run');
    assert.match(finalResultReceipt.evidenceProposalDigest ?? '', /^sha256:/,
      degradedGate.invalid.some(candidate => candidate.code === 'review_execution_authority_missing'),
      'the actual REVIEW gate keeps degraded-single-host local evidence out of native and managed authority paths',
    );
    assert.equal(degradedGate.valid.some(candidate => candidate.id === degradedPass.id), false);
    assert.deepEqual(classifyReviewerExecutionAuthority({
      executionMode: 'cross-provider-cli',
      assuranceLevel: 'ordinary-review',
      hasManagedEvidenceBinding: false,
    }), {
      classification: 'cross-provider-advisory-only',
      directSignedReviewAllowed: false,
      managedReceiptRequired: true,
      reviewGatePath: 'none',
    }, 'cross-provider CLI without a managed receipt remains advisory-only');
    store.writeReviewPasses(STORY_ID, { passes: [originalPass] });

    const findingHandlers = createHostRunHandlers(
      { store, root, scanRoot: join(root, 'packages/main') },
      { runner: async () => {
        const finalAssistantResult = JSON.stringify({
          schemaVersion: 'lattice.managed_review_final_proposal.v1',
            storyId: STORY_ID, providerAgent: LANE, lane: LANE, reviewRunId: REVIEW_RUN_ID,
            conclusion: 'findings',
            findings: [{
              desc: 'packages/main/src/example.ts:1 managed provider found a blocking behavior defect',
              severity: 'high', category: 'adversarial', files: ['packages/main/src/example.ts'],
            }],
            readManifest: { filesReadFully: ['packages/main/src/example.ts'], filesTriagedByName: [], scanEscalationReason: null },
        });
        return {
          stdout: '', stderr: '', exitCode: 0, timedOut: false, terminalReason: 'completed',
          finalAssistantResult, finalAssistantResultCount: 1, finalAssistantResultTruncated: false,
        };
      } },
    );
    const findingRun = await findingHandlers.host_run({
      host: 'codex', storyId: STORY_ID, agentType: LANE, reviewRunId: REVIEW_RUN_ID, lane: LANE,
      managedReview: true, detach: true, deadlineMs: 2_000, json: true,
    }) as HostRunDetachResult;
    await eventually(async () => (await getManagedHostRunStatus({ root, runId: findingRun.run.runId })).run.state === 'completed', 'managed finding run did not complete');
    const findingReceipt = managedHostRunReceipt(root, findingRun.run.runId);
    handlers.managed_review_evidence_import({ runId: findingRun.run.runId, receiptId: findingReceipt.receiptId });
    const importedFindings = store.readFindings(STORY_ID).findings;
    assert.equal(importedFindings.length, 1);
    assert.equal(importedFindings[0]?.agent, LANE);
    assert.equal(importedFindings[0]?.managedEvidenceBinding?.receiptId, findingReceipt.receiptId);
    assert.equal(importedFindings[0]?.desc, 'packages/main/src/example.ts:1 managed provider found a blocking behavior defect');
    assert.equal(importedFindings[0]?.severity, 'high');
    assert.equal(importedFindings[0]?.category, 'adversarial');
    assert.deepEqual(importedFindings[0]?.files, ['packages/main/src/example.ts']);
    assert.deepEqual(importedFindings[0]?.readManifest, {
      filesReadFully: ['packages/main/src/example.ts'],
      filesTriagedByName: [],
      scanEscalationReason: null,
    });
    assert.equal(
      directSignedReviewAllowed: false,
      managedReceiptRequired: true,
      reviewGatePath: 'none',
    };
  }
  return {
    classification: 'native-host-signed-review',
    directSignedReviewAllowed: true,
    managedReceiptRequired: false,
    reviewGatePath: 'direct-signed-review',
  };
}

export function resolveManagedReviewerBasePrompt(root: string, run: ReviewRun): string {
  if (run.assembledPrompt) return run.assembledPrompt;
  const body = resolvePromptRoleBody(run.lane, loadConfig(root).promptEnvelope).body;
  if (rawSha256(body) !== run.promptHash) {
    throw new Error('managed reviewer: legacy ReviewRun prompt hash does not match the canonical role body');
  }
  return body;
}

export function buildManagedReviewerPrompt(root: string, run: ReviewRun): string {
  const binding = JSON.stringify({
    storyId: run.storyId,
    providerAgent: run.lane,
    lane: run.lane,
    reviewRunId: run.reviewRunId,
  });
  return [
    '--- BEGIN MANAGED REVIEW EVIDENCE PROTOCOL ---',
    `This provider run is already bound to ${binding}.`,
    'Do not call review_run_start, review_pass_set, or finding_add in this run.',
    'Your final assistant result MUST contain exactly one JSON object and no prose, tool call, or markdown fence. Do not call managed_review_proposal_set; tool-shell output is not formal evidence.',
    'Use schemaVersion="lattice.managed_review_final_proposal.v1" and the exact bound fields above. For a pass add conclusion="pass", note, and truthful readManifest/readLog. For findings add conclusion="findings", exact findings, and truthful read evidence.',
    'The managed host adapter reads only this bounded final assistant result after provider exit, seals the exact verdict, and then permits receipt import. The controller cannot substitute or override it.',
    '--- END MANAGED REVIEW EVIDENCE PROTOCOL ---',
    '',
    resolveManagedReviewerBasePrompt(root, run),
  ].join('\n');
}

export function managedReviewerPromptDigest(root: string, run: ReviewRun): string {
  return sha256(buildManagedReviewerPrompt(root, run));
}

